# origin: s493 perlfunc index walk / pf-sort-misc.pl
my @w = qw(pear Apple fig banana); print join(",", sort @w), "\n", join(",", sort { lc $a cmp lc $b } @w), "\n", join(",", sort { length $a <=> length $b or $a cmp $b } @w), "\n", join(",", reverse sort { $a cmp $b } @w), "\n"; sub by_len { length($a) <=> length($b) } print join(",", sort by_len @w), "\n"; my $cmp = sub { $b cmp $a }; print join(",", sort $cmp @w), "\n"; my %h = (a=>3,b=>1,c=>2); print join(",", sort { $h{$a} <=> $h{$b} } keys %h), "\n"; my @recs = map { { n => $_, l => length } } @w; print join(",", map { $_->{n} } sort { $a->{l} <=> $b->{l} || $a->{n} cmp $b->{n} } @recs), "\n"; print join(",", map { $_->[1] } sort { $a->[0] <=> $b->[0] } map { [length, $_] } @w), "\n"; my @n = sort { $a <=> $b } qw(10 2 33 4); print "@n\n"; my @u = do { my %s; grep { !$s{$_}++ } qw(a b a c b) }; print "@u\n"; use List::Util qw(sum max min first reduce shuffle uniq sum0 any all none pairs); print sum(1..10), " ", max(3,9,2), " ", min(3,9,2), " ", first { $_ > 3 } (1..9); print " ", reduce { $a * $b } 1..5; print " ", join("", uniq(qw(a a b))), " ", sum0(), " ", (any { $_ == 2 } 1,2,3) ? "any" : "none", "\n"; print scalar(reverse("abc")), " ", join(",", (sort { $a <=> $b } (3,1,2))[0,-1]), " ", "@{[ map { $_ * 2 } grep { $_ % 2 } 1..6 ]}", "\n"; my @sorted = sort { $a <=> $b } (3, 1, 2); my ($lo, $hi) = @sorted[0, $#sorted]; print "$lo $hi\n"; print "last=$w[-1] $w[$#w] ", scalar(@w), " $#{[1,2,3]}\n"; my @copy = @w[1..$#w]; print "@copy\n"; my @sp = splice(@w, 1, 2, qw(X Y Z)); print "@sp | @w\n"; unshift @w, "first"; push @w, "last"; print shift(@w), pop(@w), " @w\n"; print "exists\n" if exists $w[1]; my @e = (); print "empty\n" if !@e; print "wa: ", join(",", wantarray() // "undef"), "\n"; my @aoa = ([1,2],[3,4]); print join(";", map { join(",", @$_) } @aoa), " $aoa[1][0] $aoa[1]->[1] ${$aoa[0]}[1] @{$aoa[0]}\n"; print "join: ", join("-", 1..3, "a".."c"), "\n"; my ($x, $y, @rest) = (1, 2, 3, 4); print "$x $y @rest\n"; ($x, $y) = ($y, $x); print "$x $y\n"; my $count = () = (1,2,3,4); print "$count\n"; my $lastel = (7,8,9)[-1]; print "$lastel\n"; print "lc: @{[ map { lc } qw(A B) ]}\n"; print "nested: @{[ scalar(@{[1,2,3]}) ]}\n"; print "chained: ", join(",", map { $_->[0] } grep { $_->[1] > 1 } map { [$_, length] } qw(a bb ccc)), "\n"; local $" = ":"; print "@w[0,1]\n"; my @arr2 = (1) x 3; print "@arr2\n"; print "neg-idx: $w[-2]\n"; my @del = (1..5); @del = grep { $_ != 3 } @del; print "@del\n"; print "exists-sub\n" if exists &by_len; print defined &nope ? "def" : "undef-sub", "\n"; print "ok\n";
